pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Response URL is correct", function () {
    const jsonData = pm.response.json();
    pm.expect(jsonData.url).to.eql("https://postman-echo.com/get");
});

pm.test("Successful POST request", function () {
    pm.expect(pm.response.code).to.be.oneOf([200, 201]);
});

pm.test("Response data matches request", function () {
    const response = pm.response.json();

    pm.expect(response.json.name).to.eql("Hilal");
    pm.expect(response.json.role).to.eql("Junior QA Engineer");
    pm.expect(response.json.project).to.eql("API Testing Portfolio");
    pm.expect(response.json.status).to.eql("Learning Postman");
});

pm.test("Invalid input is echoed correctly", function () {
    const response = pm.response.json();

    pm.expect(pm.response.code).to.eql(200);
    pm.expect(response.data.name).to.eql("");
    pm.expect(response.data.age).to.eql(-5);
    pm.expect(response.data.email).to.eql("invalid-email");
});
